#!/usr/bin/env bash
# Lane L76 (2026-09-26): the gateway boot helper (/usr/local/sbin/
# winn3-gateway-firewall, generated by this installer) against the
# WINVPN-INPUT layouts the certified data plane actually builds.
#
# Round SU puts `-i lo -p tcp --dport 9199 -j WINVPN-NFQ-PROBE` between the
# guard jumps and `-i lo -j ACCEPT` on every admitted node, and Round EX2 adds
# `-p tcp --dport 443 -j ACCEPT` at position 7 where 443 is an admitted
# stealth port. The helper used to require `-i lo -j ACCEPT` in slot 3, so it
# refused every such node at install and at every start of
# winn3-gateway-firewall.service, which winn3-gateway.service Requires (lane
# L75, France). And --install/--start ran that refusal only after the binary
# and env file had been replaced.
#
# Cases: the four live layouts (read-only captures in
# testdata/winn3_gateway_winvpn_input), each with and without its 9111
# rules and with the pre-Round-G ACCEPTs above the guards; the probe in every
# wrong slot and in every wrong form; unknown rules in slot 3 (still refused);
# the read-only --check-layout mode; and main --install/--start refusing
# before the first write. tools/test_deployment_runtime_configs.sh runs the
# same helper against real iptables in a netns, including the chain the
# data-plane installer itself generates.
set -euo pipefail
# In the bash macOS ships as /bin/bash (3.2.57) a failing [[ ]] does not stop
# set -e, which would silence every assertion below. Refuse such a bash.
if "${BASH}" -c 'set -e; [[ 1 == 2 ]]; exit 0'; then
  printf 'refusing to run: in %s (%s) a failing [[ ]] does not stop set -e\n' "${BASH}" "${BASH_VERSION}" >&2
  exit 2
fi
HERE="$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd -P)"
INSTALL="$(python3 -B "${HERE}/../tools/winn3_gateway_test_source.py" "${1:-${HERE}/wins_data_plane_setup_ONETOUCH.sh}" --legacy-compat)"
LAYOUTS="${HERE}/testdata/winn3_gateway_winvpn_input"
export WINN3_GATEWAY_MEMINFO="${WINN3_GATEWAY_MEMINFO:-${HERE}/testdata/winn3_gateway_meminfo/large}"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/winn3-su-probe.XXXXXX")"
trap 'rm -rf -- "${WORK}"' EXIT HUP INT TERM

fail() {
  printf 'FAIL %s\n' "$*" >&2
  exit 1
}

bash -n "${INSTALL}"
awk "/^  cat <<'EOF' # the boot helper: \\/usr\\/local\\/sbin\\/winn3-gateway-firewall\$/{f=1; next} f && /^EOF\$/{exit} f{print}" \
  "${INSTALL}" > "${WORK}/firewall"
[[ -s "${WORK}/firewall" ]] || fail "boot helper heredoc not found in ${INSTALL}"
bash -n "${WORK}/firewall"

mkdir -p "${WORK}/bin"
# The fake models WINVPN-INPUT as kernel-form (`iptables -S`) rule lines, so
# positional inserts and deletes land where real iptables would put them. It
# logs every call; any call it does not model fails with 2.
cat > "${WORK}/bin/iptables" <<'EOF'
#!/usr/bin/env python3
import os
import sys
from pathlib import Path

state = Path(os.environ["WINN3_FW_TEST_STATE"])
with open(os.environ["WINN3_FW_TEST_LOG"], "a", encoding="utf-8") as log:
    log.write("iptables " + " ".join(sys.argv[1:]) + "\n")
args = sys.argv[1:]
if args[:2] == ["-w", "10"]:
    args = args[2:]
rules = state.read_text(encoding="utf-8").splitlines() if state.exists() else []
has_chain = os.environ.get("WINN3_FW_TEST_HAS_CHAIN", "1") == "1"

def kernel(chain, spec):
    out, i = [f"-A {chain}"], 0
    while i < len(spec):
        out += spec[i:i + 2]
        if spec[i] == "-p" and "--dport" in spec:
            out += ["-m", spec[i + 1]]
        i += 2
    return " ".join(out)

if args == ["-S"]:
    print("-P INPUT DROP")
    if os.environ.get("WINN3_FW_TEST_INPUT"):
        print(os.environ["WINN3_FW_TEST_INPUT"])
    if has_chain:
        print("-N WINVPN-INPUT")
        print("\n".join(rules))
elif args == ["-S", "WINVPN-INPUT"] and has_chain:
    print("-N WINVPN-INPUT")
    print("\n".join(rules))
elif len(args) > 2 and args[0] == "-I" and args[1] == "WINVPN-INPUT" and args[2].isdigit():
    rules.insert(int(args[2]) - 1, kernel("WINVPN-INPUT", args[3:]))
    state.write_text("\n".join(rules) + "\n", encoding="utf-8")
elif len(args) > 1 and args[0] == "-D" and args[1] == "WINVPN-INPUT":
    rules.remove(kernel("WINVPN-INPUT", args[2:]))
    state.write_text("\n".join(rules) + "\n", encoding="utf-8")
else:
    sys.exit(2)
EOF
cat > "${WORK}/bin/stat" <<'EOF'
#!/usr/bin/env bash
if [[ "$*" == *"%u:%a"* ]]; then
  printf '0:600\n'
else
  exec /usr/bin/stat "$@"
fi
EOF
chmod 700 "${WORK}/bin/iptables" "${WORK}/bin/stat"
# The helper holds the shared firewall lock for its whole run (design v17
# 2.2 item 1). macOS has no flock(1), so every host uses the same fake, on a
# lock file inside the work directory.
install -m 700 "${HERE}/testdata/winn3_gateway_fake_flock.py" "${WORK}/bin/flock"
export WINS_FIREWALL_LOCK="${WORK}/wins-firewall.lock"
printf 'WINN3_GATEWAY_LISTEN=0.0.0.0:9111\n' > "${WORK}/gateway.env"
chmod 600 "${WORK}/gateway.env"

recovery='-A WINVPN-INPUT -j WINVPN-SSH-RECOVERY'
serving='-A WINVPN-INPUT -j WINVPN-LOCAL-SERVING'
probe='-A WINVPN-INPUT -i lo -p tcp -m tcp --dport 9199 -j WINVPN-NFQ-PROBE'
loopback='-A WINVPN-INPUT -i lo -j ACCEPT'
udp='-A WINVPN-INPUT -p udp -m udp --dport 9111 -j ACCEPT'
tcp='-A WINVPN-INPUT -p tcp -m tcp --dport 9111 -j ACCEPT'
ex2='-A WINVPN-INPUT -p tcp -m tcp --dport 443 -j ACCEPT'

# run_helper [ARGS...]: one helper run on ${WORK}/state; output in run.out,
# every iptables call appended to ${WORK}/log.
run_helper() {
  PATH="${WORK}/bin:${PATH}" \
    WINN3_GATEWAY_ENV_FILE="${WORK}/gateway.env" \
    WINN3_GATEWAY_EDGE_HARDENING="${WORK}/no-edge-hardening" \
    WINN3_FW_TEST_STATE="${WORK}/state" \
    WINN3_FW_TEST_LOG="${WORK}/log" \
    bash "${WORK}/firewall" "$@" > "${WORK}/run.out" 2>&1
}
mutations() {
  grep -Ec '^iptables -w 10 -[ID] ' "${WORK}/log" || true
}
# expect_accepted NAME EXPECTED-FILE INSERTS DELETES: --check-layout says yes
# and changes nothing; the boot run ends on EXPECTED with exactly that many
# inserts and deletes; a second boot run changes nothing.
expect_accepted() {
  local name="$1" expected="$2" inserts="$3" deletes="$4" rc
  cp "${WORK}/state" "${WORK}/state.before"
  : > "${WORK}/log"
  rc=0; run_helper --check-layout 9111 || rc=$?
  [[ "${rc}" == 0 ]] || { cat "${WORK}/run.out" >&2; fail "${name}: --check-layout refused (rc ${rc})"; }
  grep -Fq -- '--check-layout: WINVPN-INPUT has a verified place for UDP/TCP 9111' "${WORK}/run.out" \
    || { cat "${WORK}/run.out" >&2; fail "${name}: --check-layout did not report the verified place"; }
  [[ "$(mutations)" == 0 ]] || fail "${name}: --check-layout mutated WINVPN-INPUT"
  cmp -s "${WORK}/state" "${WORK}/state.before" || fail "${name}: --check-layout changed the chain"
  : > "${WORK}/log"
  rc=0; run_helper || rc=$?
  [[ "${rc}" == 0 ]] || { cat "${WORK}/run.out" >&2; fail "${name}: boot run refused (rc ${rc})"; }
  diff -u "${expected}" "${WORK}/state" >&2 || fail "${name}: boot run left the wrong WINVPN-INPUT"
  [[ "$(grep -Ec '^iptables -w 10 -I WINVPN-INPUT [0-9]+ ' "${WORK}/log" || true)" == "${inserts}" ]] \
    || { cat "${WORK}/log" >&2; fail "${name}: expected ${inserts} insert(s)"; }
  [[ "$(grep -Ec '^iptables -w 10 -D WINVPN-INPUT ' "${WORK}/log" || true)" == "${deletes}" ]] \
    || { cat "${WORK}/log" >&2; fail "${name}: expected ${deletes} delete(s)"; }
  : > "${WORK}/log"
  rc=0; run_helper || rc=$?
  [[ "${rc}" == 0 && "$(mutations)" == 0 ]] || fail "${name}: second boot run was not a no-op"
  diff -u "${expected}" "${WORK}/state" >&2 || fail "${name}: second boot run changed WINVPN-INPUT"
  printf 'PASS %s\n' "${name}"
}
# expect_refused NAME REASON: --check-layout and the boot run both refuse
# with REASON, and neither changes one rule.
expect_refused() {
  local name="$1" reason="$2" mode rc
  cp "${WORK}/state" "${WORK}/state.before"
  for mode in check boot; do
    : > "${WORK}/log"
    rc=0
    if [[ "${mode}" == check ]]; then run_helper --check-layout 9111 || rc=$?; else run_helper || rc=$?; fi
    [[ "${rc}" == 1 ]] || { cat "${WORK}/run.out" >&2; fail "${name}: ${mode} run exited ${rc}, want 1 (refused)"; }
    grep -Fq -- "${reason}" "${WORK}/run.out" \
      || { cat "${WORK}/run.out" >&2; fail "${name}: ${mode} run refused for the wrong reason (want: ${reason})"; }
    grep -Fq -- 'Nothing was changed.' "${WORK}/run.out" || fail "${name}: ${mode} refusal does not say nothing changed"
    [[ "$(mutations)" == 0 ]] || fail "${name}: ${mode} run mutated WINVPN-INPUT while refusing"
    cmp -s "${WORK}/state" "${WORK}/state.before" || fail "${name}: ${mode} run changed the chain while refusing"
  done
  printf 'PASS %s\n' "${name}"
}
bad_head='WINVPN-INPUT does not start with -j WINVPN-SSH-RECOVERY'

# 1. The four live layouts, as captured: already correct, untouched.
for node in uk germany canada france; do
  [[ -s "${LAYOUTS}/${node}" ]] || fail "missing capture ${LAYOUTS}/${node}"
  [[ "$(sed -n 3p "${LAYOUTS}/${node}")" == "${probe}" ]] || fail "${node} capture does not carry the probe in slot 3"
  cp "${LAYOUTS}/${node}" "${WORK}/state"
  cp "${LAYOUTS}/${node}" "${WORK}/${node}.expected"
  expect_accepted "live ${node}" "${WORK}/${node}.expected" 0 0
done
# The EX2 early 443 ACCEPT sits at position 7 of the canada capture, below
# the head, and is tolerated there.
[[ "$(sed -n 7p "${LAYOUTS}/canada")" == "${ex2}" ]] || fail "canada capture lost the EX2 443 ACCEPT at position 7"

# 2. The same layouts built before this gateway's env file existed (no 9111
#    rules, as a data-plane rebuild without the gateway leaves them): UDP goes
#    right behind the loopback ACCEPT (position 5, behind the probe) and TCP
#    right ahead of the final DROP.
for node in uk canada; do
  grep -vF -e '--dport 9111 ' "${LAYOUTS}/${node}" > "${WORK}/state"
  awk -v udp="${udp}" -v tcp="${tcp}" '
    $0 == "-A WINVPN-INPUT -j DROP" { print tcp }
    { print }
    $0 == "-A WINVPN-INPUT -i lo -j ACCEPT" { print udp }' "${WORK}/state" > "${WORK}/${node}-fresh.expected"
  [[ "$(sed -n 5p "${WORK}/${node}-fresh.expected")" == "${udp}" ]] || fail "${node}-fresh fixture setup"
  expect_accepted "fresh v3 on live ${node}" "${WORK}/${node}-fresh.expected" 2 0
done

# 3. The pre-Round-G ACCEPTs above the guards on an SU node: moved behind
#    them, UDP behind the probe and the loopback ACCEPT, TCP where it was.
{ printf '%s\n' "${tcp}" "${udp}"; grep -vFx -e "${udp}" -e "${tcp}" "${LAYOUTS}/uk"; } > "${WORK}/state"
awk -v udp="${udp}" -v tcp="${tcp}" '
  $0 == "-A WINVPN-INPUT -j DROP" { print tcp }
  { print }
  $0 == "-A WINVPN-INPUT -i lo -j ACCEPT" { print udp }' <(grep -vFx -e "${udp}" -e "${tcp}" "${LAYOUTS}/uk") \
  > "${WORK}/above.expected"
expect_accepted "legacy ACCEPTs above the guards on live uk" "${WORK}/above.expected" 2 2

# 4. The probe only in slot 3, only in its exact form.
body="$(sed -n '5,$p' "${LAYOUTS}/uk")"
put() { printf '%s\n' "$@" "${body}" > "${WORK}/state"; }
put "${probe}" "${recovery}" "${serving}" "${loopback}"
expect_refused "probe in slot 1" "${bad_head}"
put "${recovery}" "${probe}" "${serving}" "${loopback}"
expect_refused "probe in slot 2" "${bad_head}"
# Behind the loopback ACCEPT the probe is an ordinary loopback-only rule,
# which the helper has always tolerated behind the UDP ACCEPT (it cannot match
# public traffic). The allowance does not make it part of the head: UDP still
# goes right behind `-i lo -j ACCEPT`, ahead of the probe, never after it.
{ printf '%s\n' "${recovery}" "${serving}" "${loopback}" "${probe}"; grep -vFx -e "${udp}" <<<"${body}"; } > "${WORK}/state"
{ printf '%s\n' "${recovery}" "${serving}" "${loopback}" "${udp}" "${probe}"; grep -vFx -e "${udp}" <<<"${body}"; } \
  > "${WORK}/probe-slot4.expected"
expect_accepted "probe in slot 4 is not part of the head" "${WORK}/probe-slot4.expected" 1 0
put "${recovery}" "${serving}" "${probe}" "${probe}" "${loopback}"
expect_refused "probe twice" "${bad_head}"
put "${recovery}" "${serving}" "${probe}"
expect_refused "probe without the loopback ACCEPT" "${bad_head}"
put "${recovery}" "${serving}" '-A WINVPN-INPUT -i lo -p tcp -m tcp --dport 9198 -j WINVPN-NFQ-PROBE' "${loopback}"
expect_refused "probe on another port" "${bad_head}"
put "${recovery}" "${serving}" '-A WINVPN-INPUT -p tcp -m tcp --dport 9199 -j WINVPN-NFQ-PROBE' "${loopback}"
expect_refused "probe without -i lo" "${bad_head}"
put "${recovery}" "${serving}" '-A WINVPN-INPUT -i lo -p tcp -m tcp --dport 9199 -j ACCEPT' "${loopback}"
expect_refused "probe port accepted instead of jumped" "${bad_head}"
put "${recovery}" "${serving}" '-A WINVPN-INPUT -i lo -p tcp -m tcp --dport 9199 -j WINVPN-CF-STEALTH' "${loopback}"
expect_refused "probe jump to another chain" "${bad_head}"
put "${recovery}" "${serving}" '-A WINVPN-INPUT -i lo -p tcp -m tcp --dport 9199 -m comment --comment probe -j WINVPN-NFQ-PROBE' "${loopback}"
expect_refused "probe with extra matches" "${bad_head}"

# 5. Unknown rules in slot 3 are still refused (synthetic).
for rule in \
    '-A WINVPN-INPUT -p tcp -m tcp --dport 22 -j ACCEPT' \
    '-A WINVPN-INPUT -i lo -p udp -m udp --dport 53 -j ACCEPT' \
    '-A WINVPN-INPUT -j ACCEPT' \
    '-A WINVPN-INPUT -p udp -m udp --dport 9111 -j DROP' \
    "${ex2}"; do
  put "${recovery}" "${serving}" "${rule}" "${loopback}"
  expect_refused "unknown rule in slot 3: ${rule#-A WINVPN-INPUT }" "${bad_head}"
done
# ...and ahead of the TCP ACCEPT a rule that can stop TCP 9111 still is.
awk -v ex2="${ex2}" '$0 == ex2 { print "-A WINVPN-INPUT -p tcp -m tcp --dport 9000:9200 -j DROP"; next } { print }' \
  "${LAYOUTS}/canada" > "${WORK}/state"
grep -Fxq -- '-A WINVPN-INPUT -p tcp -m tcp --dport 9000:9200 -j DROP' "${WORK}/state" || fail "range fixture setup"
expect_refused "a TCP 9111 DROP where EX2 puts its 443 ACCEPT" 'a rule ahead of the TCP 9111 ACCEPT can stop or divert it'

# 6. --check-layout reads no env file and validates its argument.
cp "${LAYOUTS}/uk" "${WORK}/state"
: > "${WORK}/log"
rc=0
PATH="${WORK}/bin:${PATH}" WINN3_GATEWAY_ENV_FILE="${WORK}/does-not-exist.env" \
  WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
  bash "${WORK}/firewall" --check-layout 9111 > "${WORK}/run.out" 2>&1 || rc=$?
[[ "${rc}" == 0 ]] || { cat "${WORK}/run.out" >&2; fail "--check-layout needed an env file"; }
for arg in '' abc 0 65536 '9111 x'; do
  rc=0
  PATH="${WORK}/bin:${PATH}" WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
    bash "${WORK}/firewall" --check-layout ${arg:+"${arg}"} > "${WORK}/run.out" 2>&1 || rc=$?
  [[ "${rc}" == 2 ]] || fail "--check-layout '${arg}' exited ${rc}, want 2"
done
[[ "$(mutations)" == 0 ]] || fail "--check-layout argument checks mutated WINVPN-INPUT"
# No WINVPN-INPUT: --check-layout reports INPUT and inserts nothing there.
: > "${WORK}/log"
rc=0
PATH="${WORK}/bin:${PATH}" WINN3_FW_TEST_HAS_CHAIN=0 WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
  bash "${WORK}/firewall" --check-layout 9111 > "${WORK}/run.out" 2>&1 || rc=$?
[[ "${rc}" == 0 ]] || fail "--check-layout without WINVPN-INPUT exited ${rc}"
grep -Fq 'no WINVPN-INPUT, so UDP/TCP 9111 would be accepted in INPUT' "${WORK}/run.out" || fail "--check-layout standalone message"
[[ "$(grep -c -e ' -I ' -e ' -C ' "${WORK}/log" || true)" == 0 ]] || fail "--check-layout touched INPUT"
# ...but a half-built data plane (a guard jump in INPUT, no WINVPN-INPUT) is
# refused by --check-layout exactly as by the boot run.
rc=0
PATH="${WORK}/bin:${PATH}" WINN3_FW_TEST_HAS_CHAIN=0 WINN3_FW_TEST_INPUT='-A INPUT -j WINVPN-SSH-RECOVERY' \
  WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
  bash "${WORK}/firewall" --check-layout 9111 > "${WORK}/run.out" 2>&1 || rc=$?
[[ "${rc}" == 1 ]] || { cat "${WORK}/run.out" >&2; fail "--check-layout accepted a half-built data plane (rc ${rc})"; }
grep -Fq 'INPUT jumps to a data-plane guard chain but WINVPN-INPUT does not exist' "${WORK}/run.out" \
  || fail "--check-layout refused a half-built data plane for the wrong reason"
printf 'PASS --check-layout is read-only and needs no env file\n'

# 7. main --install/--start: the layout refusal and the forwarding preflight
#    come before the first write. Every write is a recording stub; the check
#    itself is real and runs the helper text against the fake iptables.
# run_main MODE FORWARD LAYOUT [FWD_RC]: rc in main.rc, all calls in ${WORK}/log.
run_main() {
  local mode="$1" forward="$2" layout="$3" fwd_rc="${4:-0}" rc=0
  cp "${layout}" "${WORK}/state"
  : > "${WORK}/log"
  PATH="${WORK}/bin:${PATH}" WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
    WINN3_GATEWAY_LISTEN=0.0.0.0:9111 WINN3_GATEWAY_FORWARD="${forward}" L76_FWD_RC="${fwd_rc}" \
    bash -c '
      set -euo pipefail
      # shellcheck disable=SC1090
      source "$1"
      rec() { printf "%s\n" "$*" >> "${WINN3_FW_TEST_LOG}"; }
      require_root() { :; }
      refuse_on_hub() { :; }
      mark_winn3_role() { rec "WRITE mark_winn3_role"; }
      require_supported_production_os() { :; }
      validate_config() { return 0; }
      check_gateway_egress_mtu() { return 0; }
      preflight_forwarding() { rec "PREFLIGHT forwarding"; return "${L76_FWD_RC}"; }
      verify_staged_binary() { rec "READ verify_staged_binary"; }
      ensure_service_user() { rec "WRITE ensure_service_user"; }
      install_binary() { rec "WRITE install_binary"; }
      ensure_peer_registry() { rec "WRITE ensure_peer_registry"; }
      write_env_file() { rec "WRITE write_env_file"; }
      ensure_udp_socket_buffers() { rec "WRITE ensure_udp_socket_buffers"; }
      validate_cover() { :; }
      validate_dual_auth() { :; }
      ensure_ip_forward() { rec "WRITE ensure_ip_forward"; }
      ensure_conntrack_max() { rec "WRITE ensure_conntrack_max"; }
      apply_forwarding_firewall() { rec "WRITE apply_forwarding_firewall"; exit 43; }
      preflight_resolver() { :; }
      winn3gw_render_helper() { rec "WRITE winn3gw_render_helper"; exit 42; }
      main "$2"
    ' _ "${INSTALL}" "${mode}" > "${WORK}/main.out" 2>&1 || rc=$?
  printf '%s\n' "${rc}" > "${WORK}/main.rc"
}
line_of() { grep -n -F -- "$1" "${WORK}/log" | head -1 | cut -d: -f1; }
refused_layout="${WORK}/refused.layout"
{ printf '%s\n' "${probe}" "${recovery}" "${serving}" "${loopback}"; sed -n '5,$p' "${LAYOUTS}/uk"; } > "${refused_layout}"
for mode in --install --start; do
  run_main "${mode}" 0 "${refused_layout}"
  [[ "$(cat "${WORK}/main.rc")" == 1 ]] || { cat "${WORK}/main.out" >&2; fail "main ${mode} did not refuse a bad head"; }
  grep -Fq 'Refusing to install: the gateway firewall helper would refuse WINVPN-INPUT' "${WORK}/main.out" \
    || { cat "${WORK}/main.out" >&2; fail "main ${mode} refused for another reason"; }
  grep -Fq "${bad_head}" "${WORK}/main.out" || fail "main ${mode} did not show the helper's reason"
  if grep -E '^WRITE ' "${WORK}/log" | grep -v '^WRITE mark_winn3_role$' | grep -q .; then
    cat "${WORK}/log" >&2
    fail "main ${mode} wrote before the layout refusal"
  fi
  [[ "$(mutations)" == 0 ]] || fail "main ${mode} mutated WINVPN-INPUT while refusing"
  cmp -s "${WORK}/state" "${refused_layout}" || fail "main ${mode} changed the chain while refusing"
  # Accepted: the check ran (it read the chain) before the first write.
  run_main "${mode}" 0 "${LAYOUTS}/canada"
  [[ "$(cat "${WORK}/main.rc")" == 42 ]] || { cat "${WORK}/main.out" >&2; fail "main ${mode} did not reach the unit writer on live canada"; }
  read_at="$(line_of 'iptables -w 10 -S WINVPN-INPUT')"
  write_at="$(line_of 'WRITE install_binary')"
  [[ -n "${read_at}" && -n "${write_at}" && "${read_at}" -lt "${write_at}" ]] \
    || { cat "${WORK}/log" >&2; fail "main ${mode}: the layout check did not run before install_binary"; }
  [[ "$(mutations)" == 0 ]] || fail "main ${mode}: the pre-write check mutated WINVPN-INPUT"
  # FORWARD=1: a failed forwarding preflight writes nothing either, and a
  # passing one runs exactly once, before the first write.
  run_main "${mode}" 1 "${LAYOUTS}/canada" 1
  [[ "$(cat "${WORK}/main.rc")" == 1 ]] || fail "main ${mode} ignored a failed forwarding preflight"
  grep -Fq 'Forwarding preflight failed (see errors above); refusing to install. Nothing was written.' "${WORK}/main.out" \
    || { cat "${WORK}/main.out" >&2; fail "main ${mode}: wrong forwarding refusal"; }
  if grep -E '^WRITE ' "${WORK}/log" | grep -v '^WRITE mark_winn3_role$' | grep -q .; then
    cat "${WORK}/log" >&2
    fail "main ${mode} wrote before the forwarding refusal"
  fi
  run_main "${mode}" 1 "${LAYOUTS}/canada" 0
  [[ "$(cat "${WORK}/main.rc")" == 43 ]] || { cat "${WORK}/main.out" >&2; fail "main ${mode} FORWARD=1 did not reach apply_forwarding_firewall"; }
  [[ "$(grep -c '^PREFLIGHT forwarding$' "${WORK}/log")" == 1 ]] || fail "main ${mode} ran the forwarding preflight more than once"
  [[ "$(line_of 'PREFLIGHT forwarding')" -lt "$(line_of 'WRITE install_binary')" ]] \
    || fail "main ${mode}: forwarding preflight after install_binary"
  printf 'PASS main %s refuses before the first write\n' "${mode}"
done
# --preflight reports the same refusal in its summary.
cp "${refused_layout}" "${WORK}/state"
rc=0
PATH="${WORK}/bin:${PATH}" WINN3_FW_TEST_STATE="${WORK}/state" WINN3_FW_TEST_LOG="${WORK}/log" \
  WINN3_GATEWAY_LISTEN=0.0.0.0:9111 bash -c '
    set -euo pipefail
    # shellcheck disable=SC1090
    source "$1"
    preflight_gateway_listen_layout
  ' _ "${INSTALL}" > "${WORK}/pre.out" 2>&1 || rc=$?
[[ "${rc}" == 1 ]] || fail "preflight_gateway_listen_layout accepted a bad head"
grep -Fq 'winn3-gateway-firewall.service would fail at every start' "${WORK}/pre.out" || fail "preflight_gateway_listen_layout message"
grep -Fq 'a WINVPN-INPUT layout the gateway firewall helper accepts' "${INSTALL}" || fail "--preflight summary lost the layout item"
# --preflight runs the check and feeds its summary (static: the preflight
# branch needs credentials and a staged binary to run end to end).
awk '/^main\(\) \{$/ { m = 1 } m && /if \[\[ "\$\{WINN3_GATEWAY_MODE\}" == "preflight" \]\]; then/ { p = 1 }
